insert into public.quest_fields (field_id, subject_id, name, sort_order, active)
select f, 'math', n, o, true from _math
on conflict (field_id) do update set subject_id = excluded.subject_id, name = excluded.name, sort_order = excluded.sort_order, active = excluded.active;

insert into public.quest_topics (topic_id, field_id, name, source, importance, recommended_order, active)
select m.f || '-' || lpad(c.ord::text, 3, '0'), m.f, c.name, '大学教養', 2, c.ord * 10, true
from _math m cross join lateral jsonb_array_elements_text(m.t) with ordinality as c(name, ord)
on conflict (topic_id) do update set field_id = excluded.field_id, name = excluded.name, source = excluded.source,
  importance = excluded.importance, recommended_order = excluded.recommended_order, active = excluded.active;

